from django.core.cache import cache
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from rest_framework.exceptions import PermissionDenied

class DownloadCachedReportView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, report_token):
        cache_key = f"generated_report_{report_token}"
        report_data = cache.get(cache_key)
        if not report_data:
            return Response({'error': 'Report expired or invalid token'}, status=status.HTTP_404_NOT_FOUND)

        if str(report_data.get('owner_id')) != str(request.user.id) and not request.user.is_staff:
            raise PermissionDenied("You do not have permission to download this report.")

        return Response({
            'report_token': report_token,
            'title': report_data['title'],
            'generated_at': report_data['generated_at'],
            'file_content_base64': report_data['content_base64']
        })
